(2186440, 300853, 3039, '<td valign="top">Good idea, but for me, this is a big stretch to see the Odd Couple relationship. A wall outlet and a plug attached or unattached, is not odd.</td>', 'Good idea, but for me, this is a big stretch to see the Odd Couple relationship. A wall outlet and a plug attached or unattached, is not odd.', '2006-02-27 08:29:22.000000', NULL, 1),
(2186451, 300648, 3039, '<td valign="top">Good shot, know the movie and scene, but without the title it a couple of guys ice fishing, and there is nothing odd about that!</td>', 'Good shot, know the movie and scene, but without the title it a couple of guys ice fishing, and there is nothing odd about that!', '2006-02-27 08:33:00.000000', NULL, 1),
(2186463, 300199, 3039, '<td valign="top">I like the shot, and the title fits it. Being odd, I''m not too sure. There is a lot of this going on.</td>', 'I like the shot, and the title fits it. Being odd, I''m not too sure. There is a lot of this going on.', '2006-02-27 08:36:01.000000', NULL, 1),
(2186474, 300015, 3039, '<td valign="top">Good shot. Being a Billy Joel fan I know all the words to this song. I always kid my wife about "catholic girls start much too late" I am sure you understand the gist of this.</td>', 'Good shot. Being a Billy Joel fan I know all the words to this song. I always kid my wife about "catholic girls start much too late" I am sure you understand the gist of this.', '2006-02-27 08:40:06.000000', NULL, 1),
(2186477, 300885, 3039, '<td valign="top">This is truly a great shot and composition. I do however feel that the composition only matches the challenge based on it''s title, otherwise it is an excellent photo of two flowers, and I do not find them to be odd in any way.</td>', 'This is truly a great shot and composition. I do however feel that the composition only matches the challenge based on it''s title, otherwise it is an excellent photo of two flowers, and I do not find them to be odd in any way.', '2006-02-27 08:43:35.000000', NULL, 1),
