(2187331, 299737, 50075, '<td valign="top">Heh, this gave me a good laugh. Thumbs up.</td>', 'Heh, this gave me a good laugh. Thumbs up.', '2006-02-27 14:28:20.000000', NULL, 1),
(2187332, 298812, 50075, '<td valign="top">I like the composition and colors. Nice job.</td>', 'I like the composition and colors. Nice job.', '2006-02-27 14:28:23.000000', NULL, 1),
