(2187446, 300479, 33947, '<td valign="top">Neat abstract...beautiful line. 6</td>', 'Neat abstract...beautiful line. 6', '2006-02-27 15:17:13.000000', NULL, 1),
(2187449, 300421, 6519, '<td valign="top">Not an odd couple as such, but a couple looking or acting odd - so that''s on topic :-) What a perfectly charming photo. I like the contrast of the pretty feminine outfits and props vs the very teenage expressions on their faces (great eye contact, too!).</td>', 'Not an odd couple as such, but a couple looking or acting odd - so that''s on topic :-) What a perfectly charming photo. I like the contrast of the pretty feminine outfits and props vs the very teenage expressions on their faces (great eye contact, too!).', '2006-02-27 15:18:06.000000', NULL, 1),
(2187452, 300214, 33947, '<td valign="top">You captured a great expression on both kids. Skin tones and highlights nice. 6</td>', 'You captured a great expression on both kids. Skin tones and highlights nice. 6', '2006-02-27 15:19:26.000000', NULL, 1),
(2187454, 300648, 41522, '<td valign="top">A nice tribute to both Jack and Walter and their Grumpy Old Men movie, but other than being a tribute to the original Odd Couple actors, I''m not sure how this is an odd couple?</td>', 'A nice tribute to both Jack and Walter and their Grumpy Old Men movie, but other than being a tribute to the original Odd Couple actors, I''m not sure how this is an odd couple?', '2006-02-27 15:20:35.000000', NULL, 1),
