(2194209, 300885, 28299, '<td valign="top">Clever title; nice photo!</td>', 'Clever title; nice photo!', '2006-03-01 18:13:16.000000', NULL, 1),
(2194211, 300625, 28299, '<td valign="top">Guinness - yum!</td>', 'Guinness - yum!', '2006-03-01 18:13:44.000000', NULL, 1),
(2194220, 299460, 28299, '<td valign="top">Looks like one of Jutilda''s perhaps??</td>', 'Looks like one of Jutilda''s perhaps??', '2006-03-01 18:15:23.000000', NULL, 1),
(2194223, 298812, 28299, '<td valign="top">Wow - I like the burst of color!</td>', 'Wow - I like the burst of color!', '2006-03-01 18:16:39.000000', NULL, 1),
(2194232, 300741, 28299, '<td valign="top">I love pet portraits. Nice pose captured, with that human standard pose of eye of one to chin of the other, and a good background. This could be just a tad sharper (maybe a curves/levels adjustment) with some catchlights in their eyes.</td>', 'I love pet portraits. Nice pose captured, with that human standard pose of eye of one to chin of the other, and a good background. This could be just a tad sharper (maybe a curves/levels adjustment) with some catchlights in their eyes.', '2006-03-01 18:20:15.000000', NULL, 1),
(2194335, 300679, 13688, '<td valign="top">I think a single plastic cup would have emphasized the quality beverage cheap glass I assume you were working for as well as strengthen the couple idea.  To me it seems odd that you have discarded cups with the bottle "unpopped", perhaps I just fall into your "slow" viewer category.  your white balance feels a bit off and the lettering at the bottom feels softer than it should, ie i would have gone with greater dof...just an opinion, it was a good idea you came up with.</td>', 'I think a single plastic cup would have emphasized the quality beverage cheap glass I assume you were working for as well as strengthen the couple idea.  To me it seems odd that you have discarded cups with the bottle "unpopped", perhaps I just fall into your "slow" viewer category.  your white balance feels a bit off and the lettering at the bottom feels softer than it should, ie i would have gone with greater dof...just an opinion, it was a good idea you came up with.', '2006-03-01 19:04:54.000000', NULL, 1),
(2194346, 300199, 13688, '<td valign="top">unique idea.  nicely done.  i like the crop at the top.  the unshaven part doesn''t strengthen your theme for me.</td>', 'unique idea.  nicely done.  i like the crop at the top.  the unshaven part doesn''t strengthen your theme for me.', '2006-03-01 19:08:48.000000', NULL, 1),
(2194350, 300852, 13688, '<td valign="top">the dead flowers on his side are quite clever.  i want to say i wish you hadn''t done that 2 tone thing, but perhaps it adds to the interest.   Diet  dr pepper feels strange as a prop...definitely needed some more beer for this shoot.</td>', 'the dead flowers on his side are quite clever.  i want to say i wish you hadn''t done that 2 tone thing, but perhaps it adds to the interest.   Diet  dr pepper feels strange as a prop...definitely needed some more beer for this shoot.', '2006-03-01 19:12:21.000000', NULL, 1),
(2194351, 300468, 2158, '<td valign="top">Cute shot.<br/> <br/>Where did you get that green guy?  I want one.</td>', 'Cute shot. Where did you get that green guy?  I want one.', '2006-03-01 19:12:39.000000', NULL, 1),
(2194356, 300681, 13688, '<td valign="top">I might be a redneck, or at least past my prime....I don''t know who that is :(</td>', 'I might be a redneck, or at least past my prime....I don''t know who that is :(', '2006-03-01 19:15:27.000000', NULL, 1),
(2194365, 300670, 19944, '<td valign="top">A very good photo that is nicely lit and quite sharp.  Maybe a bit of a stretch on the odd couple theme.</td>', 'A very good photo that is nicely lit and quite sharp.  Maybe a bit of a stretch on the odd couple theme.', '2006-03-01 19:19:02.000000', NULL, 1),
(2194368, 300866, 19944, '<td valign="top">This is a great take on the challenge.  It really well shot.  SHe almost looks like she''s floating.</td>', 'This is a great take on the challenge.  It really well shot.  SHe almost looks like she''s floating.', '2006-03-01 19:19:53.000000', NULL, 1),
(2194372, 300720, 19944, '<td valign="top">Very nicely shot.  It takes me back to the days of watching "The Odd Couple" wiyh my dad.</td>', 'Very nicely shot.  It takes me back to the days of watching "The Odd Couple" wiyh my dad.', '2006-03-01 19:20:28.000000', NULL, 1),
