(2200507, 298812, 40019, '<td valign="top">Beautiful picture, great detail and sharpness, nicely done.  Not sure if a bee and flower together are really that "odd" though.</td>', 'Beautiful picture, great detail and sharpness, nicely done.  Not sure if a bee and flower together are really that "odd" though.', '2006-03-04 19:52:24.000000', NULL, 1),
(2200509, 300648, 40019, '<td valign="top">Classic!  Nice find!</td>', 'Classic!  Nice find!', '2006-03-04 19:53:45.000000', NULL, 1),
(2200517, 300759, 40019, '<td valign="top">Great challenge entry!  Definitely an odd pairing.  The picture is a little soft (blurry) in some areas, I would have preferred it a little sharper and brighter (IMO).  Nice image!!</td>', 'Great challenge entry!  Definitely an odd pairing.  The picture is a little soft (blurry) in some areas, I would have preferred it a little sharper and brighter (IMO).  Nice image!!', '2006-03-04 19:55:53.000000', NULL, 1),
