(2201753, 300226, 42198, '<td valign="top">Would have been nice to see a bit of interaction between the two subjects, as it is it looks like you took a snapshot as they were walking past each other. Fits the challenge though.</td>', 'Would have been nice to see a bit of interaction between the two subjects, as it is it looks like you took a snapshot as they were walking past each other. Fits the challenge though.', '2006-03-05 15:28:32.000000', NULL, 1),
(2201754, 299010, 42198, '<td valign="top">Too small.</td>', 'Too small.', '2006-03-05 15:28:45.000000', NULL, 1),
(2201757, 300389, 42198, '<td valign="top">Great idea! - The backdrop looks a bit strange around the bottom of the can though. I like the angle here.</td>', 'Great idea! - The backdrop looks a bit strange around the bottom of the can though. I like the angle here.', '2006-03-05 15:30:21.000000', NULL, 1),
