(2201760, 300630, 42198, '<td valign="top">Remarkable. This shot is just superb. The expressions, composition, focus, everything about it. I love the angle.</td>', 'Remarkable. This shot is just superb. The expressions, composition, focus, everything about it. I love the angle.', '2006-03-05 15:32:59.000000', NULL, 1),
(2201761, 300015, 42198, '<td valign="top">I''d like to see the whole bike in the shot. But nice idea, you captured some good expressions here.</td>', 'I''d like to see the whole bike in the shot. But nice idea, you captured some good expressions here.', '2006-03-05 15:33:57.000000', NULL, 1),
(2201762, 300803, 42198, '<td valign="top">There''s some strange post-processing here - not sure what to make of the stuff in the foreground of the shot. Overall, quite surreal!</td>', 'There''s some strange post-processing here - not sure what to make of the stuff in the foreground of the shot. Overall, quite surreal!', '2006-03-05 15:34:46.000000', NULL, 1),
(2201763, 300053, 42198, '<td valign="top">I just can''t see the ''couple'' aspect here, unless I''m missing something obvious. Humourous shot though.</td>', 'I just can''t see the ''couple'' aspect here, unless I''m missing something obvious. Humourous shot though.', '2006-03-05 15:35:23.000000', NULL, 1),
(2201767, 300727, 42198, '<td valign="top">Good idea, I like the fact you got the focus sharp enough to read the text on the page. Attention to detail. Great lighting as well.</td>', 'Good idea, I like the fact you got the focus sharp enough to read the text on the page. Attention to detail. Great lighting as well.', '2006-03-05 15:36:13.000000', NULL, 1),
(2201768, 300227, 35786, '<td valign="top">LOL! love it! :0)</td>', 'LOL! love it! :0)', '2006-03-05 15:36:49.000000', NULL, 1),
(2201769, 300465, 42198, '<td valign="top">Pretty good capture. They do make an odd couple!</td>', 'Pretty good capture. They do make an odd couple!', '2006-03-05 15:37:00.000000', NULL, 1),
(2201770, 298812, 42198, '<td valign="top">Good flower macro, great colours and sharp focus. I''ve got a feeling it was shoehorned into the challenge though.</td>', 'Good flower macro, great colours and sharp focus. I''ve got a feeling it was shoehorned into the challenge though.', '2006-03-05 15:37:44.000000', NULL, 1),
(2201772, 300603, 42198, '<td valign="top">This shot really captures the imagination. Very interesting idea. The repeating pattern of the steps is put to good use. Well balanced/composed. I like.</td>', 'This shot really captures the imagination. Very interesting idea. The repeating pattern of the steps is put to good use. Well balanced/composed. I like.', '2006-03-05 15:38:32.000000', NULL, 1),
(2201777, 300820, 42198, '<td valign="top">Reasonable capture. Pity about the ''red eye'' effect on the larger dog, it''s a bit distracting. Interesting background (almost looks like snow!)</td>', 'Reasonable capture. Pity about the ''red eye'' effect on the larger dog, it''s a bit distracting. Interesting background (almost looks like snow!)', '2006-03-05 15:39:32.000000', NULL, 1),
(2201779, 300179, 42198, '<td valign="top">Not sure which two ships I should be looking at, I see five ships in the shot. Nice and sharp and clear though. Pity you didn''t isolate the subject(s) in a more obvious way.</td>', 'Not sure which two ships I should be looking at, I see five ships in the shot. Nice and sharp and clear though. Pity you didn''t isolate the subject(s) in a more obvious way.', '2006-03-05 15:40:33.000000', NULL, 1),
(2201781, 300806, 42198, '<td valign="top">Now this is surreal! - Quite humourous; I''d love to know what put this idea into your head! - Good lighting and focus.</td>', 'Now this is surreal! - Quite humourous; I''d love to know what put this idea into your head! - Good lighting and focus.', '2006-03-05 15:41:25.000000', NULL, 1),
(2201784, 300879, 42198, '<td valign="top">It would be nice if there was more ''interaction'' between the subjects, if they were facing or looking at each other.</td>', 'It would be nice if there was more ''interaction'' between the subjects, if they were facing or looking at each other.', '2006-03-05 15:42:24.000000', NULL, 1),
(2201790, 300866, 42198, '<td valign="top">She almost looks like she''s levitating! - Great idea, nicely executed. There''s a bit of funny blurring (post-processing?) going on though, around her legs and feet.</td>', 'She almost looks like she''s levitating! - Great idea, nicely executed. There''s a bit of funny blurring (post-processing?) going on though, around her legs and feet.', '2006-03-05 15:43:26.000000', NULL, 1),
(2201795, 299952, 42198, '<td valign="top">I find it slightly depressing for some reason! - Not sure what to say about this, the subject doesn''t really make me think, I don''t find it very engaging. However, it is in focus, and the composition.... well... It''s centered; not sure if that''s what I find unsettling about it.</td>', 'I find it slightly depressing for some reason! - Not sure what to say about this, the subject doesn''t really make me think, I don''t find it very engaging. However, it is in focus, and the composition.... well... It''s centered; not sure if that''s what I find unsettling about it.', '2006-03-05 15:45:01.000000', NULL, 1),
(2201799, 300195, 42198, '<td valign="top">This is weird! :) I like the way you have them posing outside their front door. Good setup, I like the chair and the tree in the background as well.</td>', 'This is weird! :) I like the way you have them posing outside their front door. Good setup, I like the chair and the tree in the background as well.', '2006-03-05 15:46:21.000000', NULL, 1),
(2201803, 300420, 42198, '<td valign="top">Nice. I like the way you''ve used the angle to make it appear as if he really is just a pounce away! Not very often this type of composition works, but here it helps to tell the story.</td>', 'Nice. I like the way you''ve used the angle to make it appear as if he really is just a pounce away! Not very often this type of composition works, but here it helps to tell the story.', '2006-03-05 15:47:26.000000', NULL, 1),
(2201805, 300848, 42198, '<td valign="top">This caught my attention, it''s quite outside the box really! I like the post-processing you''ve used. Overall it looks like one of these old worn sepia prints. The expressions are excellent.</td>', 'This caught my attention, it''s quite outside the box really! I like the post-processing you''ve used. Overall it looks like one of these old worn sepia prints. The expressions are excellent.', '2006-03-05 15:49:07.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2201807, 300724, 42198, '<td valign="top">Great idea, well executed. I like the way it''s not totally in sillouette, and that you can still see the white of her wings.</td>', 'Great idea, well executed. I like the way it''s not totally in sillouette, and that you can still see the white of her wings.', '2006-03-05 15:49:57.000000', NULL, 1),
(2201808, 298836, 35786, '<td valign="top">nice setup &amp; color cast unfortunately seems out of foucus just a bit. If you were going for the soft focus I think it went a bit too far. A PS tip or two- select the highlights (ctrl + alt + ~)  and make a seperate layer (ctrl + j) blur only that layer to retain the crisp shadows. or you could use your history brush to bring back sharpness in the details like the laces &amp; such. Again- a great idea :0) (8)</td>', 'nice setup & color cast unfortunately seems out of foucus just a bit. If you were going for the soft focus I think it went a bit too far. A PS tip or two- select the highlights (ctrl + alt + ~)  and make a seperate layer (ctrl + j) blur only that layer to retain the crisp shadows. or you could use your history brush to bring back sharpness in the details like the laces & such. Again- a great idea :0) (8)', '2006-03-05 15:50:19.000000', NULL, 1),
(2201810, 300602, 42198, '<td valign="top">I love the light/shadow and tones in this. Very nice. I like the way you''ve used the lines. :)</td>', 'I love the light/shadow and tones in this. Very nice. I like the way you''ve used the lines. :)', '2006-03-05 15:50:39.000000', NULL, 1),
