(2203573, 300271, 49873, '<td valign="top">Thank you all for your votes and comments, all were very helpful.</td>', 'Thank you all for your votes and comments, all were very helpful.', '2006-03-06 06:38:57.000000', NULL, 0),
(2203577, 300195, 39830, '<td valign="top">Thank you both for your comments. I half expected when I submitted it that there would be a few shots similar out there in the voting pool, but I really liked the concept and am pleased with the way it turned out. I tend to shoot for the pleasure of my own eye rather than the voters eyes so I''ve come to expect a few low placers. I am pleased that you two were also able to appreciate my photo.</td>', 'Thank you both for your comments. I half expected when I submitted it that there would be a few shots similar out there in the voting pool, but I really liked the concept and am pleased with the way it turned out. I tend to shoot for the pleasure of my own eye rather than the voters eyes so I''ve come to expect a few low placers. I am pleased that you two were also able to appreciate my photo.', '2006-03-06 06:41:41.000000', NULL, 0),
(2203582, 300756, 29490, '<td valign="top">I think this is an excellent photo pidge - it was very underrated imo.  My jp-the-amazing prediction was top 5, looks like I''ve jinxed all my top picks in this challenge.  21 is a ribbit of a finish though!</td>', 'I think this is an excellent photo pidge - it was very underrated imo.  My jp-the-amazing prediction was top 5, looks like I''ve jinxed all my top picks in this challenge.  21 is a ribbit of a finish though!', '2006-03-06 06:43:32.000000', NULL, 0),
(2203594, 300853, 29490, '<td valign="top">This is a swell photo Rikki, I did get it and chose it for top ten at the very least.  Silly voters :(</td>', 'This is a swell photo Rikki, I did get it and chose it for top ten at the very least.  Silly voters :(', '2006-03-06 06:48:57.000000', NULL, 0),
