(2204620, 300853, 31403, '<td valign="top"><a href="//www.dpchallenge.com/image.php?IMAGE_ID=232003" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_challenge/378/thumb/232003.jpg'', strrpos(''//images.dpchallenge.com/images_challenge/378/thumb/232003.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_challenge/378/thumb/232003.jpg"/></a> <br/> <br/>Gee, that''s a great idea you had!</td>', '  Gee, that''s a great idea you had!', '2006-03-06 14:21:21.000000', NULL, 0),
